import sys

def main():
    import sys
    input = sys.stdin.read().splitlines()
    n, m = map(int, input[0].split())
    files = input[1:n+1]
    to_delete_indices = list(map(int, input[n+1].split()))
    to_delete = [files[i-1] for i in to_delete_indices]

    def can_form_pattern(to_delete):
        if not to_delete:
            return None
        pattern = list(to_delete[0])
        for file in to_delete[1:]:
            for i in range(len(pattern)):
                if pattern[i] != file[i]:
                    pattern[i] = '?'
        candidate_pattern = ''.join(pattern)
        for file in files:
            if file not in to_delete and matches(candidate_pattern, file):
                return None
        return candidate_pattern

    def matches(pattern, file):
        if len(pattern) != len(file):
            return False
        for p, f in zip(pattern, file):
            if p != '?' and p != f:
                return False
        return True

    pattern = can_form_pattern(to_delete)
    if pattern:
        print("Yes")
        print(pattern)
    else:
        print("No")

main()
